#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);
    int t;
    cin>>t;
    while(t--) {
        int n;
        cin>>n;
        int N = 3*n;
        vector<long long> a(N);
        for(int i=0;i<N;i++) {
            cin>>a[i];
        }
        sort(a.rbegin(),a.rend());
        vector<long long> P(N+1,0);
        for(int i=0;i<N;i++) {
            P[i+1] = P[i] + a[i];
        }
        long long ans=-1;
        for(int i=0;i<=n;i++) {
            int l = 0,h = n-i;
            while(h-l>=3){
                int m1=l+(h-l)/3;
                int m2=h-(h-l)/3;
                long long v1=2LL*P[i]+P[i+2*m1]+3LL*P[N-2*i-m1];
                long long v2=2LL*P[i]+P[i+2*m2]+3LL*P[N-2*i-m2];
                if(v1<v2) {
                    l = m1;
                }
                else {
                    h = m2;
                }
            }
            for(int j = l;j<=h;j++) {
                long long curr = 2LL * P[i] + P[i+2*j]+ 3LL * P[N-2*i-j];
                ans = max(ans,curr);
            }
        }
        cout<<ans<<"\n";
    }
}
